// Convert an integer into a LogEst.  In other words, compute an
// approximation for 10*log2(x).
func Xsqlite3LogEst(tls *libc.TLS, x U64) LogEst {
	var y LogEst = int16(40)
	if x < uint64(8) {
		if x < uint64(2) {
			return int16(0)
		}
		for x < uint64(8) {
			y = int16(int32(y) - 10)
			x <<= 1
		}
	} else {
		for x > uint64(255) {
			y = int16(int32(y) + 40)
			x >>= 4
		}
		for x > uint64(15) {
			y = int16(int32(y) + 10)
			x >>= 1
		}
	}
	return LogEst(int32(a[x&uint64(7)]) + int32(y) - 10)
}

